previewCss:
.darma-loader-darma-b17-snail-trail { --accent: var(--loader-color, #65a30d); --accent-2: var(--loader-secondary-color, #a3e635); width: var(--loader-size, 130px); height: calc(var(--loader-size, 130px) * .42); position: relative; }
.darma-loader-darma-b17-snail-trail .darma-loader-darma-b17-snail-trail__slime { position: absolute; left: 4%; bottom: 8%; height: 10%; width: 0; border-radius: 999px; background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-2) 60%, transparent)); animation: darma-loader-darma-b17-snail-trail-snail-slime calc(var(--loader-speed, 1s) * 4) linear infinite; }
.darma-loader-darma-b17-snail-trail .darma-loader-darma-b17-snail-trail__snail { position: absolute; left: 4%; bottom: 8%; width: 30%; height: 74%; animation: darma-loader-darma-b17-snail-trail-snail-crawl calc(var(--loader-speed, 1s) * 4) linear infinite; }
.darma-loader-darma-b17-snail-trail .darma-loader-darma-b17-snail-trail__shell { position: absolute; left: 0; top: 4%; width: 66%; height: 76%; border-radius: 50%; background: repeating-conic-gradient(from 0deg at 50% 50%, var(--accent) 0 9%, color-mix(in srgb, #fff 30%, var(--accent)) 0 18%); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 18%, transparent); }
.darma-loader-darma-b17-snail-trail .darma-loader-darma-b17-snail-trail__foot { position: absolute; left: 0; bottom: 0; width: 100%; height: 28%; border-radius: 40% 60% 999px 999px; background: var(--accent-2); animation: darma-loader-darma-b17-snail-trail-snail-ripple calc(var(--loader-speed, 1s) * .9) ease-in-out infinite; }
.darma-loader-darma-b17-snail-trail .darma-loader-darma-b17-snail-trail__horn { position: absolute; right: 6%; top: 8%; width: 5%; height: 34%; border-radius: 3px; background: var(--accent-2); transform-origin: 50% 100%; }
.darma-loader-darma-b17-snail-trail .darma-loader-darma-b17-snail-trail__horn:nth-of-type(3) { transform: rotate(-16deg); }
.darma-loader-darma-b17-snail-trail .darma-loader-darma-b17-snail-trail__horn:nth-of-type(4) { right: 18%; transform: rotate(-32deg); }
@keyframes darma-loader-darma-b17-snail-trail-snail-crawl { 0% { transform: translateX(0); } 90%, 100% { transform: translateX(210%); } }
@keyframes darma-loader-darma-b17-snail-trail-snail-slime { 0% { width: 0; opacity: 1; } 90% { width: 88%; opacity: 1; } 98%, 100% { width: 88%; opacity: 0; } }
@keyframes darma-loader-darma-b17-snail-trail-snail-ripple { 0%, 100% { transform: scaleX(1); } 50% { transform: scaleX(.9) translateX(4%); } }

